mapper.select:
SELECT 
FROM tbl_eps_budget_template
WHERE deleted = 0

    AND template_name LIKE CONCAT('%', #{templateName}, '%')


    AND template_type = #{templateType}


    AND template_category = #{templateCategory}


    AND system_id = #{systemId}


    AND status = #{status}

ORDER BY sort_order ASC, created_time DESC

SELECT 
FROM tbl_eps_budget_template
WHERE deleted = 0 AND template_type = #{templateType}

    AND system_id = #{systemId}

ORDER BY sort_order ASC, created_time DESC

SELECT 
FROM tbl_eps_budget_template
WHERE deleted = 0 AND template_category = #{templateCategory}

    AND system_id = #{systemId}

ORDER BY sort_order ASC, created_time DESC

SELECT COUNT(1)
FROM tbl_eps_budget_template
WHERE deleted = 0 AND template_code = #{templateCode}

    AND template_id != #{excludeId}

mapper.update:
UPDATE tbl_eps_budget_template SET status = #{status}, updated_by = #{updatedBy}, updated_time = SYSDATE WHERE template_id IN
#{templateId}
AND deleted = 0

mapper.select:
SELECT 
FROM tbl_eps_budget_template
WHERE deleted = 0 AND status = 'ACTIVE'

    AND system_id = #{systemId}

ORDER BY usage_count DESC, created_time DESC

    LIMIT #{limit}

SELECT 
FROM tbl_eps_budget_template
WHERE deleted = 0 AND status = 'ACTIVE'

    AND system_id = #{systemId}


    AND created_by = #{userId}

ORDER BY last_used_time DESC, created_time DESC

    LIMIT #{limit}

SELECT FROM tbl_eps_budget_template WHERE deleted = 0 AND status = 'ACTIVE'
AND system_id = #{systemId}
AND (
tags LIKE CONCAT('%', #{tag}, '%')
)
ORDER BY sort_order ASC, created_time DESC

SELECT FROM tbl_eps_budget_template WHERE deleted = 0 AND status = 'ACTIVE' AND is_shared = 1
AND system_id = #{systemId}
ORDER BY sort_order ASC, created_time DESC
